from score import *
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
if __name__=='__main__':
    files={}
    for dataset in ['full.json','validation.json','pilot.json','lookahead-pilot.json','wave-pilot.json']:
        r=json.loads((OUT/dataset).read_text())
        for n,row in r['files'].items():
            entry=files.setdefault(n,{})
            baseline=np.loadtxt(OUT/f'{n}.base.indices',dtype=int)
            for m in row:
                indices=OUT/f'{n}.{m}.indices';frames=OUT/f'{n}.{m}.dvsi';audio=OUT/f'{n}.{m}.wav'
                fields=np.loadtxt(indices,dtype=int)
                assert np.array_equal(fields[:,:3],baseline[:,:3]),(n,m,'pitch/voicing/gain')
                assert frames.stat().st_size==len(fields)*9
                sr,x=wavfile.read(audio);assert sr==8000 and x.ndim==1 and len(x)==len(fields)*160
                trace=np.loadtxt(OUT/f'{n}.{m}.trace')
                if m not in ['base','energy']:
                    # The trace uses six significant digits, so near-ties round together.
                    loss=trace[:,2:5];chosen=loss[np.arange(len(loss)),trace[:,1].astype(int)];best=loss.min(axis=1)
                    assert np.all(chosen<=best+1e-5*np.maximum(1,abs(best))),(n,m,'argmin')
                entry[m]={'frames_sha256':sha(frames),'audio_sha256':sha(audio),'frames':len(fields),'full_scale_samples':int(np.count_nonzero((x==32767)|(x==-32768))),'choice_counts':np.bincount(trace[:,1].astype(int),minlength=3).tolist()}
    (OUT/'audit.json').write_text(json.dumps({'assertions':['All frame counts and PCM formats match.','Every candidate preserves b0, b1 and b2.','Every chosen branch minimises the recorded objective within trace rounding.','Wave, base and energy trial synthesis match normal decoding PCM byte for byte wherever rendered; enforced in score.py.'], 'files':files},indent=2))
    print(len(files),'recordings, all checks passed')

