from score import *
import random
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def load(name):return json.loads((OUT/name).read_text())
if __name__=='__main__':
    datasets={n:load(n) for n in ['pilot.json','lookahead-pilot.json','wave-pilot.json','full.json','validation.json','hardware-pilot.json','hardware-validation.json','hardware-regressions.json']}
    report={'date':'2026-09-23','scope':'D-STAR reconstruction-guided choice among original, half-blended and floating-point spectral targets. Pitch, voicing and gain fixed; the baseline remains the opt-in weighted encoder.',
      'decision':'No production changes. Keep the previous floating-point band-energy candidate as the leading research candidate. The five selectors do not establish a consistent improvement over it.',
      'limits':'Clean English speech; previous development and validation recordings, no fresh holdout or listener verdict. Reconstruction objectives are proxies for perceived quality. The lookahead variant needs one extra 20 ms frame. Other selectors use past/current available input only. No production runtime or float32 portability gate.',
      'controls':'Original-target control matches the weighted baseline frame bytes on all 86 recordings. Direct floating targets differ from the prior text-oracle route on two development files (250 frames total), so new direct controls are used. All 16 validation files and the 12 hardware-pilot inputs match the earlier float frames exactly. Model oracles supply candidate spectra, not hardware/reference targets.',
      'datasets':datasets,'audit':load('audit.json'),'tools':{},'sources':{},'inputs':{},'captures':{}}
    for path in [BASE,SELECT,ROOT/'build/vs2026/tools/ambe3000/Release/ambe3000.exe']:
        report['tools'][str(path.relative_to(ROOT))]=sha(path)
    for p in sorted(OUT.glob('*.py'))+sorted((OUT/'src').rglob('*')):
        if p.is_file():report['sources'][str(p.relative_to(OUT))]={'sha256':sha(p),'source':p.read_text()}
    for n in report['audit']['files']:
        wav=(MODELS/'heldout' if n.startswith('heldout_') else ROOT/'testdata/corpus')/f'{n}.wav'
        report['inputs'][n]={'wav_sha256':sha(wav),'base_model_sha256':sha(MODELS/f'{n}.base.model'),'energy_model_sha256':sha(MODELS/f'{n}.energy_grid.model')}
    for name,data in datasets.items():
        for n,row in data['files'].items():
            for mode,v in row.items():
                assert v['frames_sha256']==sha(OUT/f'{n}.{mode}.dvsi'),(name,n,mode)
                if not name.startswith('hardware'):continue
                audio=ROOT/v['reused_audio'] if 'reused_audio' in v else OUT/f'{n}.{mode}.hardware.wav'
                assert sha(audio)==v['audio_sha256']
                sr,x=wavfile.read(audio);assert sr==8000 and x.ndim==1 and len(x)==(OUT/f'{n}.{mode}.dvsi').stat().st_size//9*160
                report['captures'][str(audio.relative_to(ROOT))]={'sha256':sha(audio),'samples':len(x),'full_scale_samples':int(np.count_nonzero((x==32767)|(x==-32768)))}
    output=ROOT/'corpus/baselines/dstar_reconstruction.json';output.write_text(json.dumps(report,indent=2),encoding='utf-8')
    listening=OUT/'listening';listening.mkdir(exist_ok=True);rng=random.Random(290137);key={};cards=[]
    selected=[('hardware-pilot.json','arctic_slt_arctic_a0006'),('hardware-validation.json','heldout_5105-28233-0000'),('hardware-regressions.json','arctic_slt_arctic_a0012')]
    for i,(dataset,n) in enumerate(selected,1):
        row=datasets[dataset]['files'][n];source=(MODELS/'heldout' if n.startswith('heldout_') else ROOT/'testdata/corpus')/f'{n}.wav'
        ref=read_wav(source);lag=row['base']['lag'];clips=[ref[max(0,-lag):]]
        for m in ['energy','wave']:
            audio=ROOT/row[m]['reused_audio'] if 'reused_audio' in row[m] else OUT/f'{n}.{m}.hardware.wav'
            clips.append(read_wav(audio)[max(0,lag):])
        length=min(map(len,clips));clips=[c[:length] for c in clips]
        clips=[c*.08/max(float(np.sqrt(np.mean(c*c))),1e-9) for c in clips]
        peak=max(float(np.max(np.abs(c))) for c in clips)
        if peak>.95:clips=[c*.95/peak for c in clips]
        order=[0,1];rng.shuffle(order)
        for label,x in zip(['source','A','B'],[clips[0],clips[order[0]+1],clips[order[1]+1]]):
            wavfile.write(listening/f'p{i}-{label}.wav',8000,np.round(x*32767).astype(np.int16))
        key[f'p{i}']={'file':n,'A':['float energy','reconstruction selection'][order[0]],'B':['float energy','reconstruction selection'][order[1]]}
        cards.append(f'<section><h2>Pair {i}</h2>'+''.join(f'<label>{label}<audio controls preload="none" src="p{i}-{label}.wav"></audio></label>' for label in ['source','A','B'])+'</section>')
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>D-STAR reconstruction comparisons</title><style>body{max-width:800px;margin:40px auto;padding:0 20px;font:17px system-ui;background:#f5f7fa;color:#17212d}section{background:white;padding:20px;margin:20px 0;border:1px solid #d5dbe3;border-radius:12px}label{display:block;margin:12px 0}audio{display:block;width:100%;margin-top:5px}</style><h1>D-STAR reconstruction comparisons</h1><p>Three blind, level-matched comparisons of the earlier floating-point candidate and the new reconstruction-guided selector. Both use the USB decoder. The selection deliberately includes an improvement and regressions; it is not representative of the mean.</p>'''+''.join(cards)+'</html>'
    (listening/'index.html').write_text(html,encoding='utf-8');(listening/'key.json').write_text(json.dumps(key,indent=2))
    for path in listening.glob('*.wav'):
        sr,x=wavfile.read(path);assert sr==8000 and x.ndim==1 and len(x)>0 and np.max(abs(x.astype(np.int32)))<32767
    print('Saved',output,'and three listening pairs')

