#include <mbelib/mbelib.h>
#include "encoder/ambe_quant.hpp"
extern "C" {
#include "mbe_adaptive.h"
#include "ambe_common.h"
}
#include <algorithm>
#include <array>
#include <cmath>
#include <fstream>
#include <iostream>
#include <limits>
#include <sstream>
#include <string>
#include <vector>

struct Model {int b0,b1,L;float w0;float shape[56];};
bool read(std::istream& in,Model& m) {
    std::string line;if(!std::getline(in,line))return false;
    std::istringstream row(line);
    if(!(row>>m.b0>>m.b1>>m.L>>m.w0)||m.L<9||m.L>56||m.b0<0||m.b0>=120)throw 1;
    for(int l=0;l<m.L;++l)if(!(row>>m.shape[l])||!std::isfinite(m.shape[l]))throw 2;
    return true;
}
double cost(const mbe_parms& decoded,const Model& original,const Model& energy,int metric) {
    const int L=energy.L;
    mbe_parms rendered=decoded;
    if(metric==1)mbe_spectralAmpEnhanceWithRm0(&rendered);
    double target[56],got[56],mean=0,gotMean=0;
    for(int l=0;l<L;++l) {
        target[l]=metric==2?.5*(original.shape[l]+energy.shape[l]):energy.shape[l];
        got[l]=metric==1?std::log2(std::max(double(rendered.Ml[l+1]),1e-12)):double(decoded.log2Ml[l+1]);
        mean+=target[l]/L;gotMean+=got[l]/L;
    }
    double sum=0;
    for(int l=0;l<L;++l) {
        double weight=std::clamp(std::exp2(.5*(target[l]-mean)),.1,10.);
        double delta=(got[l]-gotMean)-(target[l]-mean);
        sum+=weight*delta*delta;
    }
    return sum/L;
}
struct Envelope {
    double cosine[129][256],sine[129][256],filter[24][129]={};
    Envelope() {
        const double pi=3.141592653589793;
        for(int k=0;k<=128;++k)for(int i=0;i<256;++i) {
            double window=.5-.5*std::cos(2*pi*i/255);
            cosine[k][i]=window*std::cos(2*pi*k*i/256);
            sine[k][i]=window*std::sin(2*pi*k*i/256);
        }
        double edges[26];
        double lo=2595*std::log10(1+100./700),hi=2595*std::log10(1+3800./700);
        for(int j=0;j<26;++j)edges[j]=700*(std::pow(10.,(lo+(hi-lo)*j/25)/2595)-1);
        for(int j=0;j<24;++j)for(int k=0;k<=128;++k) {
            double hz=k*8000./256;
            filter[j][k]=std::max(0.,std::min((hz-edges[j])/(edges[j+1]-edges[j]),(edges[j+2]-hz)/(edges[j+2]-edges[j+1])));
        }
    }
    std::array<double,24> analyse(const double* input)const {
        double power[129],total=0;
        for(int k=0;k<=128;++k) {
            double re=0,im=0;
            for(int i=0;i<256;++i){re+=input[i]*cosine[k][i];im+=input[i]*sine[k][i];}
            power[k]=re*re+im*im;total+=power[k];
        }
        std::array<double,24> result{};double mean=0;
        for(int j=0;j<24;++j) {
            double sum=0;for(int k=0;k<=128;++k)sum+=filter[j][k]*power[k];
            result[j]=std::log10(std::max(sum/std::max(total,1e-9),1e-5));mean+=result[j]/24;
        }
        for(auto& v:result)v-=mean;
        return result;
    }
};
int main(int argc,char**argv) try {
    if(argc!=6&&argc!=7)return 2;
    std::ifstream originalFile(argv[1]),energyFile(argv[2]);
    std::ofstream output(argv[4]),trace(argv[5]);
    if(!originalFile||!energyFile||!output||!trace)return 3;
    std::string mode=argv[3];int metric=mode=="enhanced"?1:mode=="balanced"?2:0;
    const bool control=mode=="base"||mode=="energy";
    if(!control&&mode!="log"&&mode!="enhanced"&&mode!="balanced"&&mode!="lookahead"&&mode!="wave")return 4;
    const bool render=argc==7;
    if(mode=="wave"&&!render)return 10;
    std::vector<short> input;
    std::ofstream audio;
    if(render) {
        std::ifstream raw(argv[6],std::ios::binary);if(!raw)return 11;
        short value;while(raw.read(reinterpret_cast<char*>(&value),2))input.push_back(value);
        audio.open(std::string(argv[4])+".s16",std::ios::binary);
    }
    Envelope envelope;
    mbe_parms synthesis{},enhanced{},unused{};
    mbe_initMbeParms(&synthesis,&unused,&enhanced);
    mbe_initAmbeParms_common(&synthesis,&unused,&enhanced);
    float history[160]={};
    mbe::AmbeQuantizer state(mbe::ambe2400Tables());Model original,energy;
    std::vector<Model> originals,energies;
    while(read(originalFile,original)) {
        if(!read(energyFile,energy)||original.L!=energy.L||original.b0!=energy.b0||original.b1!=energy.b1)return 5;
        originals.push_back(original);energies.push_back(energy);
    }
    if(read(energyFile,energy))return 7;
    int count[3]={};int frame=0;
    for(size_t frameIndex=0;frameIndex<originals.size();++frameIndex) {
        original=originals[frameIndex];energy=energies[frameIndex];
        double sourceWindow[256]={};
        if(render)for(int i=0;i<256;++i) {
            // Same 519-sample analysis/synthesis alignment, with 96 samples of history.
            long source=static_cast<long>(frameIndex)*160-519-96+i;
            if(source>=0&&source<static_cast<long>(input.size()))sourceWindow[i]=input[source];
        }
        const auto sourceEnvelope=render?envelope.analyse(sourceWindow):std::array<double,24>{};
        mbe_parms bestSynthesis{},bestEnhanced{};float bestAudio[160]={};
        const int first=mode=="energy"?2:0,last=mode=="base"?0:2;
        double best=std::numeric_limits<double>::infinity(),costs[3]={};int winner=-1,bestB[9]={};
        for(int index=first;index<=last;++index) {
            if(control&&index!=first)continue;
            float alpha=.5f*index,target[56];int b[9]={};
            for(int l=0;l<original.L;++l)target[l]=(1-alpha)*original.shape[l]+alpha*energy.shape[l];
            auto trial=state;
            trial.diagnosticTarget(original.b0,original.b1,original.L,original.w0,target,b);
            double loss=cost(trial.current(),original,energy,metric);
            mbe_parms trialSynthesis=synthesis,trialEnhanced=enhanced;
            float trialAudio[160]={};
            if(render) {
                char bits[49]={};auto previous=state.current();
                const auto& tables=state.tables();
                if(tables.packFields(b,bits)<0||tables.decodeParms(bits,&trialSynthesis,&previous)!=0)return 12;
                float rm0=mbe_spectralAmpEnhanceWithRm0(&trialSynthesis);
                mbe_synthesizeSpeechWithPreEnhRm0f(trialAudio,&trialSynthesis,&trialEnhanced,rm0);
                trialEnhanced=trialSynthesis;
                if(mode=="wave") {
                    double window[256];
                    for(int i=0;i<96;++i)window[i]=history[64+i];
                    for(int i=0;i<160;++i)window[96+i]=trialAudio[i];
                    auto generated=envelope.analyse(window);loss=0;
                    for(int j=0;j<24;++j){double delta=generated[j]-sourceEnvelope[j];loss+=delta*delta;}
                }
            }
            // Receding one-frame lookahead: evaluate all 3 next targets from
            // each current decoded predictor, then commit only the current frame.
            if(mode=="lookahead"&&frameIndex+1<originals.size()) {
                const auto& nextOriginal=originals[frameIndex+1];
                const auto& nextEnergy=energies[frameIndex+1];
                double futureBest=std::numeric_limits<double>::infinity();
                for(int nextIndex=0;nextIndex<3;++nextIndex) {
                    float nextAlpha=.5f*nextIndex,nextTarget[56];int nextB[9]={};
                    for(int l=0;l<nextOriginal.L;++l)nextTarget[l]=(1-nextAlpha)*nextOriginal.shape[l]+nextAlpha*nextEnergy.shape[l];
                    auto nextTrial=trial;
                    nextTrial.diagnosticTarget(nextOriginal.b0,nextOriginal.b1,nextOriginal.L,nextOriginal.w0,nextTarget,nextB);
                    futureBest=std::min(futureBest,cost(nextTrial.current(),nextOriginal,nextEnergy,metric));
                }
                loss+=futureBest;
            }
            costs[index]=loss;
            if(!std::isfinite(loss))return 6;
            if(loss<best) {
                best=loss;winner=index;std::copy(b,b+9,bestB);
                bestSynthesis=trialSynthesis;bestEnhanced=trialEnhanced;
                std::copy(trialAudio,trialAudio+160,bestAudio);
            }
        }
        state.diagnosticCommit(bestB);++count[winner];
        if(render) {
            synthesis=bestSynthesis;enhanced=bestEnhanced;std::copy(bestAudio,bestAudio+160,history);
            for(auto& sample:bestAudio)sample*=.125f;
            short samples[160];mbe_floattoshort(bestAudio,samples);audio.write(reinterpret_cast<char*>(samples),sizeof samples);
        }
        for(int k=0;k<9;++k)output<<bestB[k]<<(k==8?'\n':' ');
        trace<<frame++<<' '<<winner<<' '<<costs[0]<<' '<<costs[1]<<' '<<costs[2]<<'\n';
    }
    std::cout<<frame<<" frames, choices "<<count[0]<<' '<<count[1]<<' '<<count[2]<<'\n';
    return output&&trace?0:8;
} catch(...) {return 9;}
